export class UpdatePokemonDto {
  @IsOptional()
  @IsString()
  @Length(1, 40)
  name?: string

  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(100)
  level?: number

  @IsOptional()
  @IsIn(POKEMON_TYPES)
  primaryType?: string

  @IsOptional()
  @IsIn(POKEMON_TYPES)
  secondaryType?: string | null

  @IsOptional()
  @IsInt()
  trainerId?: number | null
}

export class UpdatePokemonDto {
  @ValidateIf((_, value) => value !== undefined)
  @IsString()
  @Length(1, 40)
  name?: string

  @ValidateIf((_, value) => value !== undefined)
  @IsInt()
  @Min(1)
  @Max(100)
  level?: number

  @ValidateIf((_, value) => value !== undefined)
  @IsString()
  primaryType?: string

  @IsOptional()
  @IsString()
  secondaryType?: string | null

  @IsOptional()
  @IsInt()
  trainerId?: number | null
}
